import "sync"

func sumPool(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	results := make(chan int, workers)

	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			local := 0
			for n := range jobs {
				local += n
			}
			results <- local
		}()
	}

	for _, n := range nums {
		jobs <- n
	}
	close(jobs)

	go func() {
		wg.Wait()
		close(results)
	}()

	total := 0
	for r := range results {
		total += r
	}
	return total
}

