package main

import (
	"context"
	"sync"
)

func produce(ctx context.Context, n int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for i := 0; i < n; i++ {
			select {
			case <-ctx.Done():
				return
			case out <- i:
			}
		}
	}()
	return out
}

func consume(ctx context.Context, in <-chan int) int {
	sum := 0
	for {
		select {
		case <-ctx.Done():
			return sum
		case v, ok := <-in:
			if !ok {
				return sum
			}
			sum += v
		}
	}
}

func run(ctx context.Context, n int) int {
	var wg sync.WaitGroup
	ch := produce(ctx, n)
	var total int
	wg.Add(1)
	go func() {
		defer wg.Done()
		total = consume(ctx, ch)
	}()
	wg.Wait()
	return total
}

