package main

const (
	white = 0 // unvisited
	gray  = 1 // in current DFS path
	black = 2 // fully explored
)

func hasCycle(adj map[int][]int, n int) bool {
	color := make([]int, n)
	var dfs func(u int) bool
	dfs = func(u int) bool {
		color[u] = gray
		for _, v := range adj[u] {
			if color[v] == gray {
				return true // back edge -> cycle
			}
			if color[v] == white && dfs(v) {
				return true
			}
		}
		color[u] = black
		return false
	}
	for u := 0; u < n; u++ {
		if color[u] == white && dfs(u) {
			return true
		}
	}
	return false
}

